def do_algebra(operators, operands):
    from operator import add, sub, mul, floordiv, pow

    op_map = {'+': add, '-': sub, '*': mul, '//': floordiv, '**': pow}

    result = operands[0]
    for i in range(len(operators)):
        result = op_map[operators[i]](result, operands[i + 1])

    return result
