def do_algebra(operators, operands):
    result = operands[0]
    for i, operator in enumerate(operators):
        if operator == '+':
            result += operands[i + 1]
        elif operator == '-':
            result -= operands[i + 1]
        elif operator == '*':
            result *= operands[i + 1]
        elif operator == '//':
            result //= operands[i + 1]
        elif operator == '**':
            result **= operands[i + 1]
    return result
